  function initTabs(root) {
    root.querySelectorAll('[data-uich-tabs]').forEach(function (tabs) {
      if (tabs.__uichInit) return; tabs.__uichInit = true;
      var btns = tabs.querySelectorAll('[data-uich-tab]');
