    root.querySelectorAll('[data-uich-qty]').forEach(function (box) {
      if (box.__uichInit) return; box.__uichInit = true;
      var input = box.querySelector('[data-uich-qty-input]');
      if (!input) return;
      var min = parseInt(input.getAttribute('min') || '1', 10);
      var maxAttr = input.getAttribute('max');
      var max = maxAttr ? parseInt(maxAttr, 10) : Infinity;
      function set(n) {
        if (isNaN(n)) n = min;
        input.value = String(Math.max(min, Math.min(max, n)));
        input.dispatchEvent(new Event('change', { bubbles: true }));
      }
      var dec = box.querySelector('[data-uich-qty-dec]');
      var inc = box.querySelector('[data-uich-qty-inc]');
      if (dec) dec.addEventListener('click', function () { set(parseInt(input.value, 10) - 1); });
      if (inc) inc.addEventListener('click', function () { set(parseInt(input.value, 10) + 1); });
      // A typed value is clamped on blur rather than per keystroke, so a
      // partially typed number is not rewritten under the cursor.
      input.addEventListener('blur', function () { set(parseInt(input.value, 10)); });
    });
  }

