      if (box.__uichInit) return; box.__uichInit = true;
      var main = box.querySelector('[data-uich-gallery-main]');
      if (!main) return;
      function activate(thumb) {
        var img = thumb.matches('img') ? thumb : thumb.querySelector('img');
        var src = thumb.getAttribute('data-uich-gallery-full')
          || (img && img.getAttribute('data-uich-gallery-full'))
          || (img && img.getAttribute('src'));
        if (!src) return;
        main.setAttribute('src', src);
        var alt = img && img.getAttribute('alt');
        if (alt) main.setAttribute('alt', alt);
