      // Mark the first thumb active so the strip agrees with the main image on
      // load. Does NOT swap the source — the main image is already the
      // product's featured photo, which is the right thing to open on.
      var first = box.querySelector('[data-uich-gallery-thumb]');
      if (first) first.setAttribute('data-active', 'true');
    });
  }

  /**
   * Star ratings a section draws itself.
   *
   * The fill width arrives on a data attribute rather than in `style` because
   * the export's settle pass re-renders the markup in a browser and computes
   * styles: an invalid `width:{{ … }}%` is dropped there, a data attribute is
   * not. So the percentage rides through the export intact and is applied here.
   *
