         * second CSS rule and survives a reload. Simple products only: a
         * variable one reads "Select options" and has to go to its own page to
         * choose a variation, so overlaying "Added" on it would describe the
         * wrong thing even when one of its variations is in the cart. */
        if (cta && cta.getAttribute('data-product-type') === 'simple') {
          cta.classList[entry ? 'add' : 'remove']('added');
        }
        if (!rm) return;
        if (entry) {
          rm.setAttribute('href', entry.href);
          rm.setAttribute('data-cart_item_key', entry.key);
          rm.classList.add('remove_from_cart_button');
        } else {
          rm.setAttribute('href', '#');
          rm.removeAttribute('data-cart_item_key');
          rm.classList.remove('remove_from_cart_button');
        }
