    root.querySelectorAll('[data-uich-filter-group]').forEach(function (group) {
      if (group.__uichInit) return; group.__uichInit = true;
      /* Scoped to the section, not the document: two listings on one page must
       * filter their own grid. Falls back to document for a section exported
       * without the wrapper. */
