      var items = scope.querySelectorAll('[data-uich-filter-item]');
      var chips = group.querySelectorAll('[data-uich-filter-all], [data-uichemy-list], button, a');
      if (!items.length || !chips.length) return;
      var norm = function (v) { return String(v == null ? '' : v).replace(/\s+/g, ' ').trim().toLowerCase(); };

      function apply(key) {
        Array.prototype.forEach.call(items, function (item) {
          var label = item.querySelector('[data-uich-filter-label]');
          var show = !key || norm(label && label.textContent) === key;
          if (show) item.removeAttribute('hidden');
          else item.setAttribute('hidden', '');
        });
      }

      Array.prototype.forEach.call(chips, function (chip) {
        chip.addEventListener('click', function (e) {
          /* Chips are <button type="button"> so there is nothing to prevent,
           * but a section may have been authored with anchors; stopping the
           * navigation is what keeps the filter in place either way. */
          e.preventDefault();
          Array.prototype.forEach.call(chips, function (other) {
            other.setAttribute('data-active', String(other === chip));
          });
          apply(chip.hasAttribute('data-uich-filter-all') ? '' : norm(chip.textContent));
        });
      });

      /* Opens on "All". The markup already says so via data-active, so this
       * only makes sure no card is left hidden by a previous state. */
      apply('');
    });
  }

  /* MY COUPONS — the card's amount and expiry made readable, and "Use
   * Discount" made to actually apply the code.
   *
   * The loop binds WooCommerce's raw coupon meta (`coupon_amount`,
   * `discount_type`, `date_expires`) and the store currency
   * (`site.option('woocommerce_currency')`) onto data attributes, because Twig
   * here has no currency formatter and no date filter that is proven on this
   * build. Each value is read from the CARD's own attribute first, then from
   * the first descendant carrying it (its value, else its text), so a binding
   * can land on whichever element the loop file targets. A value still holding
   * `{{` is an unrendered canvas token and is treated as absent.
   *
   * APPLYING goes through the Store API, the same one `initWooItems` reads:
   * GET the cart for its `Nonce` response header, POST `/cart/apply-coupon`
   * with that nonce, and on success go to the cart page (the card's
   * `data-uich-coupon-cart-url`, i.e. `{{ cart.url }}`, else the URL Woo
   * prints in `wc_add_to_cart_params`). The Store API applies to the guest
   * session too, even on an empty cart (measured live). On a rejection —
   * `Coupon "expired10" has expired.` is a 400 — WooCommerce's own message is
   * shown in the card and the code is copied, so the shopper can still paste
   * it at checkout. */
  function initCoupons(root) {
    var cards = root.querySelectorAll('[data-uich-coupon]');
    if (!cards.length) return;
    var API = '/wp-json/wc/store/v1/cart';
    var lang = document.documentElement.getAttribute('lang') || undefined;

    function has(card, name) {
      return card.hasAttribute(name) || !!card.querySelector('[' + name + ']');
    }
    function read(card, name) {
      var v = card.getAttribute(name);
      if (!v) {
        var el = card.querySelector('[' + name + ']');
        v = el ? (el.getAttribute(name) || el.textContent) : '';
      }
      v = String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
      return v.indexOf('{{') === -1 ? v : '';
    }
    function decode(s) {
      var raw = String(s == null ? '' : s);
      if (raw.indexOf('&') === -1 && raw.indexOf('<') === -1) return raw;
      if (!window.DOMParser) return raw;
      try {
        return new DOMParser().parseFromString(raw, 'text/html').documentElement.textContent || raw;
      } catch (e) { return raw; }
    }

    /* "15 OFF" -> "$15 OFF": a fixed amount in the store's currency, narrow
     * symbol (a bare "$", not "US$"), no ".00" on a whole amount. Percent and
     * free-shipping headlines are already complete as Twig prints them. */
    function money(amount, currency) {
      var n = parseFloat(amount);
      if (isNaN(n) || !/^[A-Za-z]{3}$/.test(currency) || !window.Intl || !Intl.NumberFormat) return null;
      var opts = { style: 'currency', currency: currency.toUpperCase(), currencyDisplay: 'narrowSymbol' };
      if (Math.round(n * 100) % 100 === 0) { opts.minimumFractionDigits = 0; opts.maximumFractionDigits = 0; }
      try { return new Intl.NumberFormat(lang, opts).format(n); } catch (e) {
        opts.currencyDisplay = 'symbol'; // narrowSymbol is newer than Intl itself
        try { return new Intl.NumberFormat(undefined, opts).format(n); } catch (e2) { return null; }
      }
    }
