      var type = read(card, 'data-uich-coupon-type');
      if (type !== 'fixed_cart' && type !== 'fixed_product') return;
      var el = card.querySelector('[data-uich-coupon-headline]');
      var amount = read(card, 'data-uich-coupon-amount');
      var formatted = el && amount && money(amount, read(card, 'data-uich-coupon-currency'));
      if (!formatted) return;
      /* Text nodes only, so any markup inside the headline survives. */
      var walker = document.createTreeWalker(el, 4 /* SHOW_TEXT */, null, false);
      for (var node = walker.nextNode(); node; node = walker.nextNode()) {
