    function disable(card) {
      card.querySelectorAll('[data-uich-coupon-apply]').forEach(function (b) {
        if ('disabled' in b) b.disabled = true;
        b.setAttribute('aria-disabled', 'true');
      });
    }

    /* `date_expires` is a unix timestamp, empty for a coupon that never
     * expires. Woo treats a coupon as expired once now is PAST that moment
     * (WC_Discounts::validate_coupon_expiry_date), so the same test here.
     * Left alone entirely when the design binds no expiry at all. */
    function expiry(card) {
      if (!has(card, 'data-uich-coupon-expires')) return;
      var el = card.querySelector('[data-uich-coupon-expiry]');
      var raw = read(card, 'data-uich-coupon-expires');
      var ts = parseInt(raw, 10);
      var expired = false;
      var text = 'No expiry date';
      if (raw && !isNaN(ts) && ts > 0) {
        var d = new Date(ts * 1000);
        var when;
        try { when = d.toLocaleDateString(lang, { year: 'numeric', month: 'long', day: 'numeric' }); }
        catch (e) { when = d.toDateString(); }
        expired = Date.now() > d.getTime();
        text = (expired ? 'Expired on ' : 'Valid until ') + when;
      }
      if (el) el.textContent = text;
      card.setAttribute('data-expired', String(expired));
      if (expired) disable(card);
    }

    function cartUrl(card, btn) {
      return btn.getAttribute('data-uich-coupon-cart-url')
        || read(card, 'data-uich-coupon-cart-url')
        || (window.wc_add_to_cart_params || {}).cart_url
        || '/cart/';
    }

    function fail(card, code, message) {
      var el = card.querySelector('[data-uich-coupon-message]');
      if (!el) {
        el = document.createElement('p');
        el.className = 'uich-coupon-msg';
        el.setAttribute('data-uich-coupon-message', '');
        card.appendChild(el);
      }
      el.setAttribute('role', 'alert');
      el.textContent = decode(message) || 'This coupon could not be applied.';
      card.setAttribute('data-coupon-error', 'true');
      var clip = window.navigator && window.navigator.clipboard;
      if (code && clip && clip.writeText) {
        try {
          clip.writeText(code).then(function () { card.setAttribute('data-copied', 'true'); }, function () {});
        } catch (e) { /* clipboard refused outside a user gesture */ }
      }
    }

    function apply(card, btn) {
      if (btn.disabled || btn.getAttribute('aria-disabled') === 'true' || btn.__uichBusy) return;
      var code = read(card, 'data-uich-coupon-code');
      if (!code) return;
      if (typeof fetch !== 'function') { fail(card, code, null); return; }
      btn.__uichBusy = true;
      btn.setAttribute('aria-busy', 'true');
      card.removeAttribute('data-coupon-error');
      function done() { btn.__uichBusy = false; btn.removeAttribute('aria-busy'); }
      fetch(API, { credentials: 'same-origin' })
        .then(function (r) {
          var nonce = (r.headers && (r.headers.get('Nonce') || r.headers.get('X-WC-Store-API-Nonce'))) || '';
          return fetch(API + '/apply-coupon', {
            method: 'POST',
            credentials: 'same-origin',
            headers: { 'Content-Type': 'application/json', 'Nonce': nonce },
            body: JSON.stringify({ code: code }),
          });
        })
        .then(function (r) {
          if (r.ok) { done(); window.location.assign(cartUrl(card, btn)); return; }
          return r.json()
            .catch(function () { return null; })
            .then(function (d) { done(); fail(card, code, d && d.message); });
        })
        .catch(function () { done(); fail(card, code, null); });
    }

    Array.prototype.forEach.call(cards, function (card) {
      if (card.__uichInit) return; card.__uichInit = true;
      headline(card);
      expiry(card);
      card.addEventListener('click', function (e) {
        var btn = e.target.closest && e.target.closest('[data-uich-coupon-apply]');
        if (!btn || !card.contains(btn)) return;
        e.preventDefault();
        apply(card, btn);
      });
    });
  }

  /* A COUNTDOWN re-driven from page load (under-maintenance/layout-x1).
   *
   * The design ticks with useState + setInterval, which the export drops, so
   * the clock froze on its first paint. Same contract as the React version:
   * `data-uich-countdown` is the number of seconds from page load, each
   * `data-uich-cd-unit` shows its unit zero-padded to two digits, once a
   * second, and the clock stops at zero rather than going negative. */
