    root.querySelectorAll('[data-uich-countdown]').forEach(function (box) {
      if (box.__uichInit) return; box.__uichInit = true;
      var secs = parseFloat(box.getAttribute('data-uich-countdown'));
      var units = box.querySelectorAll('[data-uich-cd-unit]');
      if (isNaN(secs) || !units.length) return;
      var target = Date.now() + Math.max(0, secs) * 1000;
      var timer = null;
      function pad(n) { return n < 10 ? '0' + n : String(n); }
      function tick() {
        var diff = Math.max(0, target - Date.now());
        var parts = {
          days: Math.floor(diff / 86400000),
          hours: Math.floor(diff / 3600000) % 24,
          minutes: Math.floor(diff / 60000) % 60,
          seconds: Math.floor(diff / 1000) % 60,
        };
        units.forEach(function (u) {
          var k = u.getAttribute('data-uich-cd-unit');
          if (Object.prototype.hasOwnProperty.call(parts, k)) u.textContent = pad(parts[k]);
        });
        if (!diff && timer) { clearInterval(timer); timer = null; }
      }
      tick();
      if (target > Date.now()) timer = setInterval(tick, 1000);
    });
  }

  /* Each hook runs in isolation: one that throws (an API this browser lacks,
   * markup a plugin rewrote) must not take the hooks after it down too. */
  function init() {
    var root = document;
    [
      initAccordions, initTabs, initCarousels, initToggles,
      initQty, initGallery, initStars,
      initWooCart, initWooItems, initWooQty,
      initFilters, initCoupons, initCountdowns
    ].forEach(function (fn) {
      try { fn(root); } catch (e) { /* leave the rest of the page working */ }
    });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
/* component behaviour (hoisted from the section's inline <script>) */
